namespace Asaas\Laravel\Tests\Services;

use Asaas\Laravel\Models\CreditCard;
use Asaas\Laravel\Models\GenericResource;

class CreditCardServiceTest extends ServiceTestCase
{
    public function test_tokenize(): void
    {
        $this->fakeResponse(['creditCardNumber' => '8829', 'creditCardBrand' => 'VISA', 'creditCardToken' => 'a1b2c3d4-0000-4000-8000-000000000001']);

        $result = asaas()->creditCard->tokenize(['customer' => 'cus_000005219613', 'creditCard' => ['holderName' => 'John Doe', 'number' => '1234567890123456', 'expiryMonth' => '11', 'expiryYear' => '2026', 'ccv' => '123'], 'creditCardHolderInfo' => ['name' => 'John Doe', 'email' => 'john.doe@example.com', 'cpfCnpj' => '24971563792', 'postalCode' => '89223005', 'addressNumber' => '123', 'phone' => '11999999999'], 'remoteIp' => '203.0.113.10']);

        $this->assertRequestSent('POST', '/v3/creditCard/tokenizeCreditCard', [], ['customer' => 'cus_000005219613', 'creditCard' => ['holderName' => 'John Doe', 'number' => '1234567890123456', 'expiryMonth' => '11', 'expiryYear' => '2026', 'ccv' => '123'], 'creditCardHolderInfo' => ['name' => 'John Doe', 'email' => 'john.doe@example.com', 'cpfCnpj' => '24971563792', 'postalCode' => '89223005', 'addressNumber' => '123', 'phone' => '11999999999'], 'remoteIp' => '203.0.113.10']);
        $this->assertInstanceOf(CreditCard::class, $result);
    }

    public function test_tokenize_rejects_missing_required_fields(): void
    {
        $this->assertValidationRejected(fn () => asaas()->creditCard->tokenize([]), ['customer', 'creditCard', 'creditCardHolderInfo', 'remoteIp']);
    }

    public function test_get_pre_authorization_config(): void
    {
        $this->fakeResponse(['daysToExpire' => 5]);

        $result = asaas()->creditCard->getPreAuthorizationConfig();

        $this->assertRequestSent('GET', '/v3/creditCard/preAuthorization/config');
        $this->assertInstanceOf(GenericResource::class, $result);
    }

    public function test_save_pre_authorization_config(): void
    {
        $this->fakeResponse(['daysToExpire' => 5]);

        $result = asaas()->creditCard->savePreAuthorizationConfig(['daysToExpire' => 5]);

        $this->assertRequestSent('POST', '/v3/creditCard/preAuthorization/config', [], ['daysToExpire' => 5]);
        $this->assertInstanceOf(GenericResource::class, $result);
    }

    public function test_save_pre_authorization_config_rejects_missing_required_fields(): void
    {
        $this->assertValidationRejected(fn () => asaas()->creditCard->savePreAuthorizationConfig([]), ['daysToExpire']);
    }
